#!/usr/bin/env python3
"""Test harness: write file(s), run binary, show exact bytes."""
import os, subprocess, sys, shutil

W = "/tmp/probe/comments/w"
BIN = "/workspace/executable"

def fresh(gomod="module example.com/proj\n\ngo 1.21\n"):
    if os.path.isdir(W):
        shutil.rmtree(W)
    os.makedirs(W)
    if gomod is not None:
        with open(os.path.join(W, "go.mod"), "w") as f:
            f.write(gomod)

def write(name, content):
    p = os.path.join(W, name)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as f:
        f.write(content.encode() if isinstance(content, str) else content)

def run(*args, cwd=W):
    r = subprocess.run([BIN] + list(args), cwd=cwd,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return r.returncode, r.stdout, r.stderr

def vis(b):
    """Visible representation: show every byte's structure."""
    if isinstance(b, str): b = b.encode()
    out = []
    for line in b.split(b"\n"):
        out.append(line.decode("utf-8", "replace").replace("\t", "\\t").replace("\r", "\\r"))
    return "\n".join("|" + l for l in out[:-1]) + ("\n|" + out[-1] + "<NO-TRAILING-NL>" if out[-1] else "\n<ends with exactly one final newline>" if not b.endswith(b"\n\n") else "\n<ENDS WITH BLANK LINE(S)>")

def show(label, code, out, err, showerr=True):
    print("=" * 70)
    print("### " + label)
    print("EXIT=%d" % code)
    print("--- STDOUT (%d bytes) ---" % len(out))
    print(vis(out))
    if showerr:
        print("--- STDERR ---")
        sys.stdout.write(err.decode("utf-8", "replace"))
    print()

def case(label, src, *flags, gomod="module example.com/proj\n\ngo 1.21\n", fname="a.go", showerr=True):
    fresh(gomod)
    write(fname, src)
    args = list(flags) + [fname]
    code, out, err = run(*args)
    show(label, code, out, err, showerr)
    return code, out, err

def stdout_case(label, src, *flags, **kw):
    return case(label, src, "-output", "stdout", *flags, **kw)

